update public.cms_sections set data='{"eyebrow": "SECTOR EXPERTISE", "heading": "Transportation Built Around the Industries We Serve", "description": "Every industry places different demands on transportation. LMI aligns equipment, safety practices and coordination with the requirements of each sector, across Pakistan.", "action": {"label": "Explore Industries", "path": "#industries"}, "image": "/industries/overview/section-1-main-image.png", "imageAlt": "LMI trucks across industrial settings", "imagePlaceholder": "[Photo: LMI trucks across industrial settings]"}'::jsonb,revision=70 where page_id='industries' and key='sectionOne';
update public.cms_sections set data='{"eyebrow": "Explore industries", "heading": "Transportation Across Demanding Operating Environments", "industries": [{"title": "Manufacturing & Industrial", "description": "Raw materials, components, machinery and finished goods moved between suppliers, plants, warehouses and customers.", "image": "/industries/overview/section-2-image-1.png", "imageAlt": "manufacturing plant delivery", "imagePlaceholder": "[Photo: manufacturing plant delivery]", "action": {"label": "Explore Manufacturing & Industrial", "path": "/industries/manufacturing-industrial"}}, {"title": "Construction & Engineering", "description": "Bitumen, machinery, steel and construction materials delivered to project sites across Pakistan.", "image": "/industries/overview/section-2-image-2.png", "imageAlt": "construction site delivery", "imagePlaceholder": "[Photo: construction site delivery]", "action": {"label": "Explore Construction & Engineering", "path": "/industries/construction-engineering"}}, {"title": "Automotive", "description": "Vehicles, parts and equipment moved on purpose-built car carriers and road freight.", "image": "/industries/overview/section-2-image-3.png", "imageAlt": "car carrier", "imagePlaceholder": "[Photo: car carrier]", "action": {"label": "Explore Automotive", "path": "/industries/automotive"}}, {"title": "Chemicals & Petrochemicals", "description": "Chemicals, fertilizers and liquid cargo handled with suitable equipment and trained drivers.", "image": "/industries/overview/section-2-image-4.png", "imageAlt": "chemical tanker", "imagePlaceholder": "[Photo: chemical tanker]", "action": {"label": "Explore Chemicals & Petrochemicals", "path": "/industries/chemicals-petrochemicals"}}, {"title": "Oil, Gas & Energy", "description": "Crude oil, condensate and refined petroleum products moved with safety-focused practices.", "image": "/industries/overview/section-2-image-5.png", "imageAlt": "petroleum tanker", "imagePlaceholder": "[Photo: petroleum tanker]", "action": {"label": "Explore Oil, Gas & Energy", "path": "/industries/oil-gas-energy"}}], "futureIndustry": {"heading": "[Possible next page: Food, Agri & FMCG]", "description": "Wheat, sugar, edible oil and other bulk commodities. Not built yet."}}'::jsonb,revision=70 where page_id='industries' and key='sectionTwo';
update public.cms_sections set data='{"eyebrow": "Trusted by", "heading": "Automotive and Corporate Clients", "description": "With decades of experience in Pakistan’s transport industry, LMI supports businesses that need vehicles and cargo delivered safely and on time. Our operations follow ISO 9001 certification standards.", "logoPlaceholder": "[logo]", "clients": [{"id": "daewoo", "name": "Daewoo", "image": "/industries/automotive/logo-1.png", "placeholder": false}, {"id": "automotive-one", "name": "[Automotive client]", "image": "/industries/automotive/logo-2.png", "placeholder": true}, {"id": "automotive-two", "name": "[Automotive client]", "image": "/industries/automotive/logo-3.png", "placeholder": true}, {"id": "corporate-fleet", "name": "[Corporate fleet client]", "image": "/industries/automotive/logo-4.png", "placeholder": true}], "highlights": [{"heading": "[Project or client reference]", "description": "[Add a real vehicle-transport reference here: client, scale and route.]"}, {"heading": "Safety record", "description": "Recognized for safety performance by BP Pakistan (2001) and awarded for road safety participation."}], "testimonial": {"quote": "[Client testimonial: two to three sentences about working with LMI]", "attribution": "[Name], [Job Title], [Company]"}}'::jsonb,revision=70 where page_id='industries--automotive' and key='sectionFive';
update public.cms_sections set data='{"eyebrow": "Services we use", "heading": "Transportation Solutions for Automotive Needs", "services": [{"title": "Car Carrier & Vehicle Transport", "description": "Secure vehicle transportation using purpose-built car carriers.", "image": "/industries/automotive/section-4-image-1.png", "imageAlt": "Car carrier", "imagePlaceholder": "[Photo: car carrier]", "action": {"label": "Explore Car Carrier Services", "path": "/services"}}, {"title": "Full Truckload (FTL)", "description": "Dedicated capacity for parts and components moving in volume.", "image": "/industries/automotive/section-4-image-2.png", "imageAlt": "Full truckload", "imagePlaceholder": "[Photo: full truckload]", "action": {"label": "Explore Full Truckload", "path": "/services/full-truckload-ftl"}}, {"title": "Dry Cargo Transportation", "description": "Packaged and palletized parts for plants, warehouses and dealers.", "image": "/industries/automotive/section-4-image-3.png", "imageAlt": "Dry cargo", "imagePlaceholder": "[Photo: dry cargo]", "action": {"label": "Explore Dry Cargo", "path": "/services/dry-cargo-transportation"}}, {"title": "Flatbed & Project Cargo", "description": "Open-deck transport for workshop, plant and industrial equipment.", "image": "/industries/automotive/section-4-image-4.png", "imageAlt": "Flatbed equipment", "imagePlaceholder": "[Photo: flatbed equipment]", "action": {"label": "Explore Flatbed & Project", "path": "/services/flatbed-transportation"}}]}'::jsonb,revision=70 where page_id='industries--automotive' and key='sectionFour';
update public.cms_sections set data='{"eyebrow": "VEHICLES & PARTS", "heading": "Vehicle & Automotive Transportation in Pakistan", "description": "LMI moves vehicles, parts and equipment across Pakistan with purpose-built car carriers, careful loading and coordinated delivery from pickup to handover.", "action": {"label": "Discuss Your Requirement", "path": "/contact-us"}, "image": "/industries/automotive/section-1-main-image.png", "imageAlt": "Car carrier loaded with vehicles", "imagePlaceholder": "[Photo: car carrier loaded with vehicles]"}'::jsonb,revision=70 where page_id='industries--automotive' and key='sectionOne';
update public.cms_sections set data='{"eyebrow": "How we work", "heading": "Care Begins Before the Carrier Moves", "paragraphs": ["Moving vehicles is about more than getting them from A to B. The number of vehicles, their type, the pickup location and the receiving site all affect how a carrier should be configured and loaded, so we plan these details before the vehicle arrives.", "Vehicles are positioned and secured according to the carrier’s configuration, then unloaded in a controlled manner at the destination. An assured fleet network of verified trucks and drivers is ready exactly when required, which keeps dealer, fleet and corporate schedules on time.", "Our drivers follow our HSE protocols, including pre-trip inspection of the carrier before every dispatch."], "action": {"label": "Learn more about our HSSE standards", "path": "/hsse"}, "panelHeading": "Care from loading to handover", "image": "/industries/automotive/section-2-main-image.png", "imageAlt": "Vehicle carrier loaded with cars", "imagePlaceholder": "[Photo: vehicle carrier loaded with cars]", "steps": [{"number": "1", "heading": "Loading coordination", "description": "Align carrier type and vehicle readiness before loading begins."}, {"number": "2", "heading": "Positioning and securing", "description": "Vehicles placed and secured according to the carrier configuration."}, {"number": "3", "heading": "Carrier readiness", "description": "Equipment checked before dispatch."}, {"number": "4", "heading": "Controlled unloading and handover", "description": "Careful unloading at the destination, completed per your receiving requirements."}]}'::jsonb,revision=70 where page_id='industries--automotive' and key='sectionThree';
update public.cms_sections set data='{"eyebrow": "Trusted by", "heading": "Leading Industrial Names", "description": "LMI supports fertilizer, chemical and manufacturing businesses that depend on safe, on-time transportation. Our operations follow ISO 9001 certification standards.", "logoPlaceholder": "[logo]", "clients": [{"id": "engro", "name": "Engro", "image": "/industries/chemicals-and-petrochemicals/logo-1.png", "placeholder": false}, {"id": "nfml", "name": "NFML", "image": "/industries/chemicals-and-petrochemicals/logo-2.png", "placeholder": false}, {"id": "novatex", "name": "Novatex", "image": "/industries/chemicals-and-petrochemicals/logo-3.png", "placeholder": false}, {"id": "cnergyico", "name": "Cnergyico", "image": "/industries/chemicals-and-petrochemicals/logo-4.png", "placeholder": false}, {"id": "apag", "name": "APAG", "image": "/industries/chemicals-and-petrochemicals/logo-5.png", "placeholder": false}], "highlights": [{"heading": "Fertilizer logistics", "description": "Urea lifted from seaports and delivered to destinations across Pakistan for NFML and Engro."}, {"heading": "Safety record", "description": "Recognized for safety performance by BP Pakistan (2001) and awarded for road safety participation."}], "testimonial": {"quote": "[Client testimonial: two to three sentences about working with LMI]", "attribution": "[Name], [Job Title], [Company]"}}'::jsonb,revision=70 where page_id='industries--chemicals-petrochemicals' and key='sectionFive';
